(async () => {
  const at = Number(localStorage.getItem('abx_bearer_at') || 0);
  const cur = localStorage.getItem('abx_bearer') || '';
  const fresh = cur && at && (Date.now() - at) < 12 * 3600e3;
  if (fresh) return JSON.stringify({ok: true, src: 'cached', len: cur.length});
  const src = [...document.querySelectorAll("script[src*='main']")].map(s => s.src)[0];
  if (!src) return JSON.stringify({ok: !!cur, src: 'kept-no-main', len: cur.length});
  const t = await (await fetch(src, {credentials: 'omit'})).text();
  const m = t.match(/Bearer ([A-Za-z0-9%/+=]{80,})/);
  if (!m) return JSON.stringify({ok: !!cur, src: 'kept-no-match', len: cur.length});
  localStorage.setItem('abx_bearer', m[1]);
  localStorage.setItem('abx_bearer_at', String(Date.now()));
  return JSON.stringify({ok: true, src: 'refreshed', len: m[1].length});
})()

// x-search step: SearchTimeline (POST-only) — tweets with views, sorted desc
(async () => {
  const ARGS = {{args_json}};
  try {
    if (!ARGS.q) return JSON.stringify({ok: false, err: 'args_json needs q'});
    const bearer = localStorage.getItem('abx_bearer');
    const ct0 = (document.cookie.match(/(?:^|;\s*)ct0=([^;]+)/) || [])[1];
    const features = JSON.parse(localStorage.getItem('abx_ct_features'));
    if (!bearer || !ct0 || !features) return JSON.stringify({ok: false, err: 'missing bearer/ct0/features - session not set up'});
    const r = await fetch('/i/api/graphql/KPSo2_UWdOMpPJwjhfT1Qg/SearchTimeline', {
      method: 'POST', credentials: 'include',
      headers: {
        'content-type': 'application/json',
        'authorization': 'Bearer ' + bearer,
        'x-twitter-auth-type': 'OAuth2Session',
        'x-csrf-token': ct0,
        'x-twitter-client-language': 'en',
        'x-twitter-active-user': 'yes'
      },
      body: JSON.stringify({
        variables: {rawQuery: ARGS.q, count: ARGS.count || 20, querySource: 'typed_query', product: ARGS.product || 'Top'},
        features, fieldToggles: {withPayments: false}
      })
    });
    const t = await r.text();
    let j = null; try { j = JSON.parse(t); } catch {}
    if (!r.ok) return JSON.stringify({ok: false, status: r.status, err_head: t.slice(0, 160)});
    const tweets = [];
    const pick = (ic) => {
      const res = ic && ic.tweet_results && ic.tweet_results.result;
      const core = res && res.__typename === 'TweetWithVisibilityResults' ? res.tweet : res;
      if (!core || !core.legacy) return;
      const u = core.core && core.core.user_results && core.core.user_results.result;
      tweets.push({
        id: core.legacy.id_str,
        sn: u ? ((u.core && u.core.screen_name) || (u.legacy && u.legacy.screen_name)) : null,
        views: core.views ? Number(core.views.count) : null,
        fav: core.legacy.favorite_count,
        text: core.legacy.full_text
      });
    };
    const walk = (entries) => {
      for (const e of (entries || [])) {
        const c = e && e.content;
        if (!c) continue;
        if (c.itemContent) pick(c.itemContent);
        if (c.items) for (const it of c.items) pick(it.item && it.item.itemContent);
      }
    };
    for (const ins of ((j.data && j.data.search_by_raw_query && j.data.search_by_raw_query.search_timeline && j.data.search_by_raw_query.search_timeline.timeline && j.data.search_by_raw_query.search_timeline.timeline.instructions) || [])) walk(ins.entries);
    const seen = new Set();
    const uniq = tweets.filter(x => x.id && !seen.has(x.id) && seen.add(x.id));
    uniq.sort((a, b) => (b.views || 0) - (a.views || 0));
    const top = uniq.slice(0, ARGS.top || 20).map(x => ({...x, text: x.text.slice(0, 200)}));
    return JSON.stringify({ok: true, q: ARGS.q, count: uniq.length, tweets: top});
  } catch (e) {
    return JSON.stringify({ok: false, err: e.name + ': ' + e.message});
  }
})()
